python3 - <<'EOF'
p='tools/marble05/spark/render.html'
s=open(p).read()
start=s.index('let n = 0;')
end=s.index('</script></body>')
s=s[:start]+'''let n = 0; const t0 = performance.now(); console.log("initialized", (t0 / 1000).toFixed(1));
// done when the picture is non-empty and stable over 3 consecutive frames (Spark sorts splats in a worker)
const probe = document.createElement("canvas"); probe.width = 108; probe.height = 192;
const pctx = probe.getContext("2d", { willReadFrequently: true });
let last = -1, stable = 0;
renderer.setAnimationLoop(() => {
  renderer.render(scene, cam); n++;
  pctx.drawImage(renderer.domElement, 0, 0, 108, 192);
  const d = pctx.getImageData(0, 0, 108, 192).data; let s = 0; for (let i = 0; i < d.length; i += 4) s += d[i] + d[i + 1] + d[i + 2];
  const m = s / (108 * 192 * 3);
  stable = (m > 5 && last > 0 && Math.abs(m - last) / last < 0.003) ? stable + 1 : 0; last = m;
  console.log("frame", n, ((performance.now() - t0) / 1000).toFixed(1), m.toFixed(2));
  if ((stable >= 3 && n >= +(q.get("frames") || 6)) || n >= 400) {
    renderer.setAnimationLoop(null); window.__png = renderer.domElement.toDataURL("image/png"); window.__frames = n; window.__done = true;
  }
});
'''+s[end:]
open(p,'w').write(s)
EOF
